about_disclaimer_title: "Avvertenza",
about_disclaimer_purpose: "ps5upload è fornito esclusivamente per scopi di ricerca, didattica, interoperabilità e sviluppo homebrew. Non è affiliato, approvato o collegato a Sony Interactive Entertainment Inc. «PlayStation» e «PS5» sono marchi di Sony Interactive Entertainment Inc., usati qui solo a fini identificativi.",
about_disclaimer_piracy: "Usalo solo con hardware di tua proprietà e con contenuti che possiedi legalmente. Non deve essere utilizzato per copiare, distribuire o eseguire software che non hai il diritto di usare.",
about_disclaimer_risk: "Questo software è fornito «così com'è», senza alcuna garanzia. Utilizzare una console modificata può danneggiarla in modo permanente, distruggere irreversibilmente salvataggi e licenze e causare il ban dell'account o della console. Lo usi interamente a tuo rischio e ti assumi la piena responsabilità delle conseguenze. Prima di iniziare, esegui il backup di tutto ciò che non puoi permetterti di perdere.",
