"connection_prior_killed": "L’helper precedente non si è chiuso correttamente",
"connection_prior_killed_detail": "Può significare che un altro payload sulla console l’ha terminato, che il sistema ha esaurito la memoria o che si è bloccato. Lo stderr.log in una segnalazione di bug dice quale. Se carichi ps5upload con un autoloader, prova invece a inviarlo da qui.",
