fs_upload_interrupted_notice: "Una copia sulla PS5 è stata interrotta. Apri File per riprenderla.",
installed_launch_smp_refused: "La PS5 ha rifiutato di avviare questo gioco (0x80940033) anche se kstuff è in esecuzione. ShadowMount+ monta un gioco quando viene avviato, e non è successo. Chiudi qualsiasi gioco in esecuzione, invia di nuovo ShadowMount+ da Payloads, poi premi Gioca.",
connection_mac_local_network_hint: "macOS potrebbe bloccare l'accesso di questa app alla rete locale. Apri Impostazioni di Sistema → Privacy e sicurezza → Rete locale, consenti PS5Upload, poi controlla di nuovo.",
