kept_intro: "Le cartelle che ps5upload scrive su questa console e quanto contiene ciascuna. I file temporanei e di prova si possono ripulire; i tuoi pacchetti e i backup dei salvataggi da qui si aprono soltanto, non vengono mai eliminati.",
