"fpkg.run.what_pkg": "un pacchetto (.pkg)",
"fpkg.run.what_ps4_pkg": "un pacchetto PS4 (.pkg)",
connection_payload_engine_unreachable: "L'app non è riuscita a raggiungere il proprio motore su questo computer, quindi non può sapere se l'helper è partito sulla PS5. Non è un problema della PS5: l'avviso in cima alla finestra dice perché e può riavviare il motore. Poi premi di nuovo Invia helper. ({error})",
"engine_problem.missing.fix": "Ripristina ps5upload-engine dalla quarantena dell'antivirus (o consentilo), oppure reinstalla l'app.",
"engine_problem.missing.why": "Il programma del motore manca dalla cartella dell'app. I software di sicurezza a volte lo mettono in quarantena.",
"engine_problem.port.fix": "Premi Riavvia motore. Se non funziona, consenti ps5upload-engine nel firewall o nell'antivirus, poi riavvia l'app.",
"engine_problem.port.why": "Qualcosa occupa l'indirizzo del motore ({url}) ma non risponde: un altro programma su quella porta, o un software di sicurezza che blocca le connessioni.",
"engine_problem.proxy.fix": "Disattiva il proxy o lo strumento VPN per gli indirizzi locali (127.0.0.1), oppure avvia l'app senza l'impostazione http_proxy / ALL_PROXY.",
"engine_problem.proxy.why": "Le richieste al motore sono andate a un proxy impostato su questo computer invece che al motore.",
"engine_problem.remote.fix": "Controlla che il motore (container Docker o altro computer) sia in esecuzione e raggiungibile a quell'indirizzo, oppure cambialo in Impostazioni.",
"engine_problem.remote.why": "Il motore che questa app deve usare ({url}) non risponde.",
"engine_problem.restart": "Riavvia motore",
"engine_problem.slow.fix": "Premi Riavvia motore. Anche firewall o antivirus che filtrano le connessioni locali possono causarlo: consenti ps5upload-engine.",
"engine_problem.slow.why": "Il motore è in esecuzione ma non risponde.",
"engine_problem.stopped.fix": "Premi Riavvia motore. Se si ferma di nuovo, la schermata Log mostra perché.",
"engine_problem.stopped.why": "Il motore non è in esecuzione: si è fermato o non è mai partito.",
"engine_problem.title": "L'app non raggiunge il proprio motore su questo computer",
"engine_problem.phone.title": "L'app non riesce a raggiungere il suo motore",
"engine_problem.phone.why": "Il motore funziona dentro questa app e ha smesso di rispondere.",
"engine_problem.phone.fix": "Chiudi completamente l'app e riaprila.",
"engine_problem.web.fix": "Controlla che il server (container Docker) sia in esecuzione, poi ricarica questa pagina.",
"engine_problem.web.why": "Questa pagina ha perso la connessione al server ps5upload da cui proviene.",
gate_engine_down_body_v2: "Questa schermata ha bisogno del motore dell'app, che non risponde. L'avviso in cima alla finestra dice perché e può riavviarlo.",
"profile.np.body": "Fa trattare alla PS5 l'account connesso come se avesse effettuato l'accesso a PlayStation Network, senza contattare Sony. Alcune funzioni della console si aprono solo a un account connesso, tra cui Remote Play. Usa np-fake-signin di earthonion, scaricato dalla pagina del progetto quando premi il pulsante.",
"profile.np.confirm_title": "Far accedere questo account?",
"profile.np.failed": "L'accesso non è stato eseguito",
"profile.np.fetching": "Download di np-fake-signin…",
"profile.np.sending": "Invio alla PS5…",
"profile.np.sent": "np-fake-signin {version} è stato eseguito sulla PS5. Riavvia la PS5 per finire; l'account risulterà connesso e Impostazioni > Sistema > Remote Play si potrà attivare.",
"profile.np.sign_in": "Accedi",
"profile.np.state_loading": "Lettura dell'account…",
"profile.np.state_no_slot": "Nessun account qui sopra si chiama {user}, quindi np-fake-signin si fermerebbe. Dai all'account lo stesso nome dell'utente connesso, oppure attivane uno per lui.",
"profile.np.state_no_user": "Nessun utente ha effettuato l'accesso sulla PS5. Accedi al profilo che vuoi, poi torna qui.",
"profile.np.state_not_activated": "{user} (account {slot}) non ha ancora un ID account. Attivalo prima in Account qui sopra.",
"profile.np.state_ready": "Pronto: {user} (account {slot}) è attivato.",
"profile.np.step_activate": "L'account ha bisogno di un ID account. Un account collegato a PSN ce l'ha; altrimenti attivalo in Account qui sopra (attivazione offline).",
"profile.np.step_run": "Premi Accedi mentre quell'utente è connesso sulla PS5. Viene eseguito una volta e si chiude.",
"profile.np.title": "Accedi a PlayStation Network (offline)",
