fs_send_dial_hint: "Lascia vuoto per usare l'indirizzo della console stessa. Con ps5-tailscale imposta un inoltro locale sulla console mittente (la sua pagina di stato: 127.0.0.1:19120 → l'altra console:9120) e inserisci qui 127.0.0.1:19120. Chi può inviare è deciso dalle chiavi delle console e da un ticket monouso, non dall'indirizzo.",
