"installed_uninstall_no_copy": "La tua Collezione su questo computer non ha una copia di questo gioco: conserva il suo pacchetto da qualche parte prima di disinstallarlo.",
"connection_send_payload_moved": "Vuoi inviare un altro payload (kstuff, etaHEN, qualsiasi .elf)? Si trova in Payload → Invia payload. Questa schermata invia solo l'helper di PS5Upload.",
"connection_send_payload_open": "Apri Invia payload",
"upload_elf_title": "Questo è un payload (.elf), non un gioco",
"upload_elf_body": "Caricarlo copia soltanto il file. ShadowMount+ rileva le cartelle di gioco (con eboot.bin e sce_sys) e le immagini di gioco, mai un .elf, quindi non comparirà nella schermata Home. Per eseguirlo, invialo invece al loader della console. Ciò che va caricato è un'app homebrew fornita come immagine .ffpkg o .exfat, o come cartella con eboot.bin.",
"netdoctor.hint.below_test": "Questo caricamento va a {speed}, molto al di sotto dei {expected} misurati dal test di velocità.",
"netdoctor.hint.runs_at": "Questo caricamento va a {speed}.",
"netdoctor.hint.cause_source": "A rallentarlo è la lettura dei file su questo computer, non la rete: un'unità USB o un disco rigido, una condivisione di rete (NAS) o l'estrazione di un archivio sono più lenti del collegamento. Copiare prima il gioco su un SSD interno, o caricare i file di un archivio dopo averlo estratto, dà la piena velocità.",
"netdoctor.hint.cause_disk": "A rallentarlo è l'unità della PS5, non la rete: un'unità USB esterna, un'unità quasi piena o migliaia di file piccoli (ognuno costa il suo tempo) scrivono più lentamente di quanto il collegamento fornisca. Un'immagine di gioco (.ffpkg o .exfat) viaggia come un solo file.",
"netdoctor.hint.cause_workers": "La PS5 sta ancora scrivendo ciò che ha ricevuto, non sta aspettando la rete. Con molti file piccoli ognuno costa il suo tempo; un'immagine di gioco (.ffpkg o .exfat) viaggia come un solo file.",
"netdoctor.hint.cause_cap": "A rallentarlo è il limite di velocità di caricamento (circa {cap} MiB/s, in questa schermata e nelle Impostazioni). Impostalo a 0 per rimuoverlo.",
"profile.np.confirm_body_v2": "np-fake-signin scrive sulla PS5 i file e le impostazioni di accesso a PlayStation Network per {user}. Non viene inviato nulla a Sony. Riavvia la PS5 dopo.",
"profile.np.side_effect": "Effetto collaterale noto: in seguito alcune console chiedono di «Disattivare temporaneamente le restrizioni della console PS5» prima di aprire qualsiasi gioco, e Impostazioni > Utenti e account > Altro > Disconnetti può restare disattivato. L'app conserva prima sulla PS5 una copia di tutto ciò che np-fake-signin modifica, quindi Annulla accesso qui lo ripristina.",
"profile.np.backing_up": "Salvataggio sulla PS5 di una copia delle impostazioni attuali dell'account…",
"profile.np.backup_failed": "La PS5 non ha potuto conservare una copia delle impostazioni dell'account, quindi np-fake-signin non è stato eseguito. Sostituisci l'helper con la versione di questa app e riprova. ({error})",
"profile.np.step_restart_v2": "Riavvia la PS5. Per annullare in seguito, premi Annulla accesso qui e riavvia di nuovo.",
"profile.np.undo": "Annulla accesso",
"profile.np.undo_hint": "Sulla PS5 è conservata una copia delle impostazioni di questo account di prima dell'accesso; questo la ripristina.",
"profile.np.undo_confirm_title": "Annullare l'accesso?",
"profile.np.undo_confirm_body": "Riporta le impostazioni e i file di {user} com'erano prima di np-fake-signin. Riavvia la PS5 dopo. Le funzioni che richiedono un account connesso, tra cui Remote Play, potrebbero non aprirsi finché non accedi di nuovo.",
"profile.np.undoing": "Ripristino delle impostazioni…",
"profile.np.undone": "Ripristinato ({count} impostazioni e file). Riavvia la PS5 per completare.",
"profile.np.no_backup": "Questo account ha le impostazioni del modello di np-fake-signin (data di nascita 1983-04-12, flag adulto offline disattivato) e su questa PS5 non c'è alcuna copia di prima, quindi l'app non può annullarlo. Se ora la PS5 chiede di disattivare temporaneamente le restrizioni della console prima di aprire i giochi: Impostazioni > Famiglia e filtro famiglia > Restrizioni della console PS5 (codice 0000 se non l'hai cambiato), e togli lì le restrizioni.",
"linkdl.lz4_title": "Questo link è compresso con LZ4",
"linkdl.image_title": "Questo link è un'immagine di gioco",
"linkdl.lz4_help": "ps5upload può decomprimerlo durante il download, così la PS5 riceve il file decompresso. Su questo computer non viene salvato nulla e la PS5 ha bisogno di spazio solo per il file decompresso.",
"linkdl.lz4_unpack": "Decomprimi durante il trasferimento",
"linkdl.lz4_unpack_hint": "Disattivato: il file .lz4 viene salvato sulla PS5 così com'è.",
"linkdl.image_hint": "Un'immagine di gioco {kind}. ShadowMount+ la monta così com'è da una cartella che analizza, come homebrew su un'unità. Il file compare lì solo quando è completo.",
"pm_add_failed": "Impossibile salvare {name} in Payload Manager",
"pm_catalogue_match": "Catalogo: {name}",
"pm_replace_tooltip": "Payload Manager non registra la versione di un payload aggiunto a mano, quindi ps5upload non può sapere se questo è più vecchio. Sostituendolo, al suo posto viene salvata la versione del catalogo, mantenendo la sua posizione nella lista di avvio; poi gli aggiornamenti vengono proposti qui.",
