"payloads_description_running": "I programmi in esecuzione sulla PS5 in questo momento e le porte in uso con ciò che di solito vi ascolta. Puoi fermare o riavviare un programma; attenzione ai processi di sistema, fermare quello sbagliato può bloccare la console.",
