"ps4move_experimental": "Sperimentale: rimettere salvataggi in formato PS4 su una PS5 non funziona sempre, e un gioco potrebbe non caricarli. Prova prima un gioco; il suo salvataggio PS5 viene conservato e puoi rimetterlo dalle copie del gioco.",
"ps4move_safety": "La PS4 viene solo letta, mai modificata. I suoi salvataggi vengono prima copiati su questo computer. Sulla PS5 si toccano solo i giochi scelti, il salvataggio di ognuno viene copiato prima di essere sostituito e nient'altro (utenti, file di sistema, trofei) cambia.",
