"fpkg.merge.update_label": "Un aggiornamento PS4 per questo gioco",
"fpkg.merge.hint": "Un pacchetto, un'immagine o una cartella. L'aggiornamento deve essere dello stesso titolo e più recente del gioco.",
"fpkg.merge.browse": "Sfoglia",
"fpkg.merge.ok": "✓ {title}: {from} diventa {to}. L'aggiornamento sostituisce {replaced} file e ne aggiunge {added}.",
"fpkg.merge.pick_game": "Scegli il gioco PS4 a cui appartiene questo aggiornamento",
"fpkg.merge.pick_update": "Scegli un aggiornamento PS4 per questo gioco",
"fpkg.image.zstd": "Pacchetti di risorse zstd (i più piccoli, per ShadowMount+)",
"fpkg.image.zstd_body": "Raccoglie tutto tranne i file di sistema del gioco in pacchetti zstd, scritti direttamente nell'immagine senza copia temporanea. L'immagine riceve ampr-emu-ng di quer3q come emulatore, verificato con un digest pubblicato prima dell'uso. Un gioco già in pacchetti LZ4 viene convertito. Disattiva update_emulators in ShadowMount+, altrimenti può sostituire l'emulatore con uno che non sa leggerli.",
"fpkg.image.zstd_level": "Livello di compressione",
"fpkg.image.zstd_runtime": "Runtime dei pacchetti",
"fpkg.image.zstd_runtime_latest": "Ultima versione (predefinita)",
"fpkg.image.zstd_runtime_pinned": "Testata {version}",
"fpkg.image.zstd_runtime_body": "«Ultima» usa la release più recente di ampr-emu-ng su GitHub solo se corrisponde allo SHA-256 che GitHub pubblica per essa; altrimenti, o offline, viene usata la testata {version}. «Testata» usa sempre {version}.",
"fpkg.folder.zstd_body": "Scrive il gioco come cartella normale, con tutto tranne i file di sistema in pacchetti zstd e ampr-emu-ng di quer3q come fakelib/libSceAmpr.sprx. Anche una cartella di gioco può essere la sorgente. I pacchetti LZ4 qui non sono disponibili: vanno solo in un'immagine .exfat. Disattiva update_emulators in ShadowMount+, altrimenti può sostituire l'emulatore con uno che non sa leggerli.",
"ampr_emu_add_hint": "Questo gioco legge i file tramite AMPR e non ha un emulatore. Alcuni giochi così non si avviano da un'immagine senza, altri funzionano bene. Aggiunge ampr_emu 0.4.2.1 di drakmor, scaricato una volta e controllato con un digest noto. L'immagine non cambia: l'emulatore va in una cartella backport di ShadowMount+.",
"ampr_emu_done_backport": "Aggiunto come backport di ShadowMount+ in {folder}. L'immagine non è cambiata. Avvia il gioco per provare.",
"ampr_emu_done_folder": "Aggiunto alla cartella del gioco, {folder}. Avvia il gioco per provare.",
"fpkg.fake_sign_note": "{count} eseguibili semplici (non firmati) di questo gioco ricevono una firma fittizia durante la conversione, altrimenti non si avvierebbe. La sorgente non cambia.",
"fpkg.image.ampr_emu": "Aggiungi l'emulatore AMPR",
"fpkg.image.ampr_emu_body": "Questo gioco legge i file tramite AMPR e non ha un emulatore. Alcuni giochi così non si avviano da un'immagine senza, altri funzionano bene. Aggiunge ampr_emu 0.4.2.1 di drakmor come fakelib/libSceAmpr.sprx, scaricato una volta dalla release GitHub e controllato con un digest noto.",
"fpkg.image.lz4_placement_note": "Tieni un'immagine compressa in pacchetti nella memoria interna della console: è stato segnalato un blocco su schermo nero da USB. Disattiva update_emulators in ShadowMount+, altrimenti può sostituire l'emulatore con uno che non legge i pacchetti.",
"smp_rescan": "Scansiona ora",
"smp_rescan_done": "ShadowMount+ sta eseguendo la scansione. Rileva le nuove immagini e riprova i giochi che non si sono montati.",
