"rp_err_rp_off": "Riproduzione remota è disattivata sulla PS5. Sulla console apri Impostazioni › Sistema › Riproduzione remota e attiva Abilita Riproduzione remota (se risulta già attiva, disattivala e riattivala), poi premi Avvia. In grigio? L'account dell'utente PS5 deve essere attivato, e una PS5 passata all'ambiente NP sp-int la tiene disattivata: riportala su np.",
"rp_err_refused": "La PS5 ha rifiutato di avviare Riproduzione remota. Sulla console controlla Impostazioni › Sistema › Riproduzione remota › Abilita Riproduzione remota (disattivala e riattivala), premi Consenti in Gioca › Configura, oppure associa di nuovo. Il codice qui sotto dice quale rifiuto era. Ancora rifiutato? Riavvia la PS5: una console accesa da molto può rifiutare finché non si riavvia.",
"web_update_how_docker": "Per aggiornare, esegui questo nella cartella del tuo file compose (anche Watchtower può farlo per te):",
"web_update_how_app": "Questa pagina viene da PS5Upload su un altro computer. Aggiorna l'app lì e questa pagina si aggiornerà con essa.",
