"rpg_user_title": "Accedi con un utente sulla PS5",
"rpg_user_body": "Sulla console scegli l'utente con cui giocherai. Nessuno deve restare davanti allo schermo, ma l'utente deve avere eseguito l'accesso. Se l'utente ha un codice di accesso, Gioca lo chiede quando premi Avvia.",
