"rpg_service_body": "Impostazioni › Sistema › Riproduzione Remota › Abilita Riproduzione Remota. L'app può attivarla per te e, dal firmware 10.00 in poi, consentirla anche per questo utente. Se poi Avvia dice che Remote Play è disattivato, attivalo nelle Impostazioni della PS5 stessa: conta l'interruttore della console.",
"rpg_rest_title": "Consenti di riattivare la PS5 dalla modalità riposo",
"rpg_rest_body": "Impostazioni › Sistema › Risparmio energetico › Funzioni disponibili in modalità riposo: attiva «Rimani connesso a Internet» e «Abilita l'accensione della PS5 dalla rete». Senza di esse una console in modalità riposo non si può riattivare e la sua rete si spegne dopo pochi secondi. Solo la console può mostrarle.",
