"dump_decrypt_risk": "La decrittazione può bloccare la console",
"dump_decrypt_risk_body": "Per decriptare, l'helper sostituisce brevemente, per ogni eseguibile, una parte del sistema usata da tutti i programmi. Se il gioco legge un file in quel momento la console può bloccarsi e richiedere uno spegnimento forzato. Resta nella schermata iniziale del gioco nel frattempo. Solo firmware fino a 13.60; sui firmware più recenti il dump è una copia semplice.",
