"rp_picture_here": "Immagine su questo dispositivo",
"rp_picture_here_hint": "Se disattivato, i nuovi stream partono qui senza immagine, audio né controller, risparmiando CPU e batteria di questo dispositivo. Gli amici in Play Together e Go live ricevono comunque lo stream, e puoi riattivarlo dallo stream in qualsiasi momento.",
"rp_picture_off_title": "L'immagine è disattivata su questo dispositivo",
"rp_picture_off_body": "Lo stream continua per i tuoi amici e la tua trasmissione. Qui non ci sono nemmeno audio e controller, quindi questo dispositivo non ha quasi nulla da fare.",
"rp_picture_turn_on": "Attiva l'immagine",
"rp_picture_turn_off": "Disattiva l'immagine su questo dispositivo",
"golive_picture_hint": "Se disattivato, questo computer inoltra lo stream senza decodificarlo né mostrarlo, risparmiando CPU e calore. Lascia l'app aperta; il controllo resta qui.",
"pt_picture_hint": "Se disattivato, questo dispositivo invita solo i tuoi amici: niente immagine, audio o controller qui, e la loro partita continua. Per giocare sulla TV.",
"pt_tv_title": "Giochi sulla TV?",
"pt_tv_note": "Questo stream ha effettuato l'accesso con l'utente PS5 associato a PS5Upload. Premi PS sul DualSense della console e scegli un altro utente: quello sei tu sulla TV. Scegliere l'utente dello stream termina lo stream per tutti, amici compresi. Alcuni giochi contano anche l'utente dello stream come giocatore, il che può lasciare un posto in meno per un amico.",
"pt_tv_seats": "Una PS5 accetta 4 controller. Con il tuo DualSense sulla TV, il primo amico usa il controller dello stream e gioca come il suo utente, senza sceglierne uno, e altri 2 hanno un controller proprio: c'è posto per 3 amici.",
"pt_stream_seat_note": "Un amico sta usando il controller di questo stream, quindi il tuo controller qui non gioca finché non esce.",
