helper_copy_place_pldmgr: "Payload Manager",
helper_copy_place_etahen: "payload etaHEN",
helper_copy_place_autoloader: "autoloader",
helper_boot_label: "Carica l'helper di PS5Upload all'avvio",
helper_boot_hint: "Payload Manager avvia l'helper dopo tutto ciò che lo precede nella sua lista di avvio, così Minion e questa app funzionano dopo un riavvio senza PC. A ogni connessione questa app aggiorna quella copia al proprio helper e conserva la precedente; se una nuova copia non parte dopo un riavvio, viene rimessa la precedente.",
helper_boot_list_off: "La lista di avvio di Payload Manager è disattivata qui sopra, quindi all'avvio non parte nulla finché non la attivi.",
helper_boot_list_off_title: "La lista di avvio di Payload Manager è disattivata",
helper_boot_list_off_confirm: "Finché la lista di avvio è disattivata, Payload Manager non avvia nulla all'accensione, nemmeno l'helper. Attivarla?",
helper_boot_turn_on_list: "Attiva la lista di avvio",
helper_boot_not_listed: "L'helper è salvato ma non è nella lista di avvio di Payload Manager. Questa app lo rimette alla prossima connessione.",
helper_boot_bad_version: "L'helper {version} non è partito all'avvio di questa PS5, quindi è stata rimessa la copia precedente. Una versione più recente dell'app riproverà.",
helper_boot_needs_pm: "Caricare l'helper di PS5Upload all'avvio richiede Payload Manager: è lui ad avviare l'helper quando parte la PS5.",
helper_boot_failed: "Impossibile cambiare il caricamento dell'helper all'avvio",
helper_boot_on_title: "Ora l'helper si carica all'avvio",
helper_boot_restored_title: "L'helper non è partito all'avvio",
helper_boot_restored_body: "La PS5 si è riavviata ma l'helper {version} conservato da Payload Manager non è partito, quindi questa app ne ha inviato uno. La copia precedente è di nuovo in Payload Manager e parte al prossimo riavvio. Questa app non salverà più {version} lì.",
helper_copies_updated_title: "Helper aggiornato",
helper_copies_updated_body: "La tua PS5 avvierà l'helper {version} al prossimo riavvio.",
helper_copies_failed_title: "Impossibile aggiornare l'helper che la PS5 avvia all'accensione",
helper_copies_failed_body: "Ancora il vecchio helper: {list}. La PS5 lo riavvia dopo ogni riavvio. Per sistemarlo a mano, scarica ps5upload.elf {version} dalla pagina delle release e copialo sopra quel file (schermata File, FTP o l'unità USB), oppure caricalo di nuovo in Payload Manager con lo stesso nome. ({error})",
helper_mismatch_boot_copy: "La PS5 ha avviato una copia più vecchia dell'helper che conserva per l'accensione ({list}). Premi Invia helper: questa app invia l'helper corrispondente e aggiorna anche quella copia, così la PS5 avvia quello nuovo dopo un riavvio.",
