mcp_api_nav: "MCP e API",
mcp_tab_connect: "Collega un agente",
mcp_tab_tools: "Strumenti dell'agente",
mcp_tab_api: "API",
mcp_phone_title: "Da configurare su un computer",
mcp_phone_body: "Il motore di questa app per telefono serve solo all'app. Per usare un agente o uno script, avviali su un computer con PS5Upload aperta o con il motore Docker.",
mcp_other_computer_title: "Questo motore è su un altro computer",
mcp_other_computer_body: "Un agente su quel computer può seguire questi passaggi con il proprio indirizzo 127.0.0.1. Un agente altrove deve avere anche il suo indirizzo nell'impostazione PS5UPLOAD_ALLOW_IP del motore.",
mcp_intro: "MCP permette a un agente IA di gestire la tua PS5 con strumenti che capisce: inviare file, installare giochi, controllare le temperature e altro. Aggiungilo una volta, poi basta chiedere.",
mcp_address: "Indirizzo MCP",
mcp_agents_title: "Aggiungilo al tuo agente",
mcp_check_again: "Controlla di nuovo",
mcp_after_adding: "Avvia una nuova sessione nell'agente per caricarlo. Tieni aperta PS5Upload mentre l'agente lavora: il server MCP fa parte del suo motore.",
mcp_update_title: "Tenerlo aggiornato",
mcp_update_app: "Quando PS5Upload si aggiorna, qui non devi fare nulla. Gli agenti ricevono gli strumenti dal motore, quindi quelli nuovi compaiono alla prossima sessione. Una sessione già aperta mantiene il vecchio elenco.",
mcp_update_address: "Se l'indirizzo del motore cambia, l'app te lo dice all'avvio e la scheda dell'agente mostra Aggiorna. Basta un clic.",
mcp_update_by_hand: "L'app non vede Gemini CLI, Cursor, Claude Desktop o i tuoi script. Se l'indirizzo qui cambia, o uno di questi non si connette più dopo un aggiornamento, copia di nuovo la sua configurazione da Altri agenti e app.",
mcp_update_version: "Questo motore è la versione {version}. Per vedere a cosa è collegato un agente, chiedigli qual è la versione del motore di PS5Upload.",
mcp_bridge_body: "Esegue il programma ponte del motore invece di usare questo indirizzo. Funziona lo stesso. Aggiorna lo passa all'indirizzo.",
mcp_stale_toast: "Un agente ha ancora il vecchio indirizzo del motore e non riesce a connettersi. Aggiornalo in MCP & API.",
mcp_stale_open: "Apri",
mcp_try_title: "Poi prova a chiedere",
mcp_try_status: "Quanto è calda la mia PS5 in questo momento?",
mcp_try_space: "Cosa occupa più spazio sulla mia PS5?",
mcp_try_install: "Installa questo pacchetto sulla mia PS5 e dimmi quando ha finito.",
mcp_safety_title: "Un agente può fare tutto ciò che puoi fare tu",
mcp_safety_body: "Non c'è una password e può eliminare file dalla console. Lascia su \"ask\" gli strumenti che modificano qualcosa e leggi ogni comando per la console prima di consentirlo.",
mcp_safety_read_only: "Per farlo solo guardare, imposta questo nell'ambiente del motore e riavvia il motore:",
mcp_access_label: "Gli agenti possono modificare",
mcp_access_hint: "Disattivato: gli agenti possono solo guardare, ad esempio elencare i file, leggere lo stato e seguire i trasferimenti. Non cambia nulla.",
mcp_access_locked: "Disattivato, impostato dall'ambiente del motore.",
mcp_access_failed: "Impossibile modificarlo: {error}",
mcp_access_limit: "Questo impedisce agli agenti di usare gli strumenti di PS5Upload; un programma che può eseguire comandi su questo computer potrebbe comunque raggiungere il motore.",
