cb_restore_title: "Cosa ripristinare",
cb_restore_hint: "I file con lo stesso nome sulla PS5 vengono sostituiti. Nient'altro viene eliminato. I salvataggi vengono prima salvati.",
cb_users_title: "Quali salvataggi vanno a chi",
cb_users_hint: "Una PS5 resettata ha utenti nuovi, anche con gli stessi nomi. Un salvataggio può andare solo nel salvataggio di quell'utente per il gioco, quindi avvia prima ogni gioco una volta con lui e salva.",
