cb_tab_guide: "Se la tua PS5 non si avvia",
cb_title: "Backup e ripristino",
cb_desc: "Tieni su questo computer ciò che vale la pena conservare e recuperalo dopo un reset.",
cb_no_console: "Collegati prima a una PS5.",
cb_step_restart: "Riavvia ed entra di nuovo in Modalità provvisoria",
cb_step_restart_body: "La Modalità provvisoria può aprirsi mostrando solo l'ultima opzione, Ripristina PS5 (reinstalla il software di sistema). Secondo alcuni utenti, scegliendo Riavvia PS5 ed entrando di nuovo in Modalità provvisoria tornano le altre opzioni. Prova prima questo.",
cb_step_repair: "Ripara l'archiviazione della console",
cb_step_repair_body: "Controlla l'unità e la ripara. Non cancella nulla, quindi è la prima vera opzione da provare.",
cb_step_rebuild: "Cancella la cache e ricostruisci il database",
cb_step_rebuild_body: "Ricostruisce l'elenco dei contenuti della console. Mantiene giochi e salvataggi. Su una console con jailbreak, giochi e app registrati a mano potrebbero doversi registrare di nuovo. Alcuni dicono che sia bastato, ma non lo abbiamo confermato.",
cb_step_defaults: "Ripristina le impostazioni predefinite",
cb_step_defaults_body: "Riporta le impostazioni ai valori predefiniti e mantiene giochi e salvataggi.",
cb_step_reset: "Ripristina PS5",
cb_step_reset_body: "Cancella utenti, giochi e salvataggi. Non tocca il software di sistema installato, quindi il firmware non cambia e non serve un'unità USB. Se le opzioni sopra non hanno aiutato, usa questa.",
cb_step_reinstall: "Ripristina PS5 (reinstalla il software di sistema)",
cb_step_reinstall_body: "L'ultima risorsa: rimuove anche il software di sistema e richiede un file di reinstallazione su un'unità USB. Il sito Sony offre solo la versione più recente, quindi usare il suo file aggiorna il firmware e può far finire il jailbreak.",
cb_usb_format: "Formatta l'unità come FAT32 o exFAT.",
cb_usb_folders: "Crea una cartella chiamata PS5 e, al suo interno, una cartella chiamata UPDATE, in maiuscolo.",
cb_usb_file: "Salvaci il file come PS5UPDATE.PUP. Deve essere il file di reinstallazione, molto più grande del file di aggiornamento.",
cb_usb_refused: "Se la PS5 dice ancora di non trovare il file, controlla questi tre punti e poi prova un'altra unità: alcune non funzionano.",
cb_after_offline: "Configura la PS5 senza collegarla a internet e rifiuta qualsiasi aggiornamento di sistema proposto. Un aggiornamento può far finire il jailbreak.",
cb_after_user: "Ricrea i tuoi utenti. In Account trovi i passaggi per dare a un nuovo utente il suo vecchio ID account.",
cb_after_jailbreak: "Rifai il jailbreak della console e invia l'helper, poi apri questa schermata e ripristina il backup.",
cb_enter_title: "Come entrare in Modalità provvisoria",
cb_enter_body: "Spegni la PS5. Tieni premuto il tasto di accensione fino al secondo bip, circa sette secondi. Collega il controller con un cavo USB e premi il tasto PS.",
cb_steps_title: "Cosa provare, in quest'ordine",
cb_steps_hint: "Ogni passo costa più del precedente. Fermati appena la PS5 si avvia.",
cb_erases: "Cancella i tuoi dati",
