"pairing_closed_body_v4": "Questa PS5 chiede prima che un nuovo dispositivo si connetta, e ora mostra questo come in attesa. Su un dispositivo che usa già questa PS5 (Connessione), o sulla pagina della PS5 stessa (Impostazioni › Dispositivi), premi Consenti: questa app entra da sola. Oppure premi Invia di nuovo l'helper, che fa entrare questa app.",
