"cw_tn_sign_out_confirm": "Disconnettere questa PS5 da Tailscale? Dimentica l'accesso: dovrai accedere di nuovo, e potrebbe ricevere un nuovo indirizzo. Per fermarla per un po', disattivala invece.",
"cw_tn_sub": "Gioca su questa PS5 ovunque tramite la tua rete Tailscale. Solo Remote Play e PS5Upload possono raggiungerla in questo modo. Puoi configurarlo anche dall'app PS5Upload: Connessione › Tailscale per questa PS5.",
