"cw_tn_allow_none": "Solo i dispositivi che aggiungi possono raggiungere questa PS5 tramite Tailscale. Apri PS5Upload una volta a casa su ogni dispositivo, oppure spunta i dispositivi nell'app (Connessione › Tailscale per questa PS5).",
