"settings_description_v2": "App: questo dispositivo e le scelte per tutte le console. Questa PS5: le impostazioni proprie di una console.",
"settings_tab_app": "App",
"settings_tab_ps5": "Questa PS5",
"settings_group_network": "Gioca insieme e Tailscale",
"tn_title_device": "Tailscale su questo dispositivo",
"settings_ps5_none_title": "Ancora nessuna PS5",
"settings_ps5_none_body": "Aggiungi la tua PS5 nella schermata Connessione, poi qui trovi le sue impostazioni.",
"settings_ps5_open_connection": "Apri Connessione",
"settings_ps5_picker": "PS5",
"settings_ps5_picker_hint": "Queste impostazioni valgono solo per questa PS5. Ogni tua console ha le sue, e la seguono sugli altri tuoi dispositivi.",
"auto_bringup_hint_ps5": "Quando il caricatore di questa PS5 (elfldr, porta 9021) è attivo e l'helper non è in esecuzione, l'app esegue da sola l'avvio rapido: la playlist di avvio di questa PS5 se ne hai impostata una, poi l'helper, poi la tua playlist del caricatore automatico. Una volta a ogni avvio di questa PS5; dopo la modalità riposo viene reinviato solo l'helper. Aspetta circa 90 secondi dopo la comparsa del caricatore, così il caricatore automatico della console può finire prima. Disattivato per impostazione predefinita.",
"bringup_playlist_label_ps5": "Playlist di avvio per questa PS5 (kernel R/W, SMP)",
"bringup_playlist_hint_ps5": "Viene eseguita prima dell'helper durante l'avvio rapido. I payload dipendono dal firmware, quindi ogni PS5 ha la sua. Crea le playlist in Payload.",
"upload_auto_redeploy_on_wake_hint_ps5": "Quando l'helper di questa PS5 va offline (modalità riposo, cambio di Wi-Fi o crash di un payload), continua a provare a reinviarlo in background, così l'helper, la soglia ventola di questa PS5 e la porta di caricamento tornano da soli appena è di nuovo raggiungibile. Attivato per impostazione predefinita.",
"keep_ps5_awake_mode_hint_ps5": "Azzera il timer di standby automatico di questa PS5 così non va in modalità riposo. «Durante caricamenti e installazioni» protegge i caricamenti lunghi (una causa comune di caricamenti falliti; predefinito). «Sempre quando connesso» tiene questa PS5 fuori dalla modalità riposo finché il suo helper è in esecuzione e l'app è aperta. Mettere tu la PS5 in riposo funziona comunque in ogni modalità.",
"upload_rest_after_hint_ps5": "Quando la coda di caricamento di questa PS5 finisce, chiedile di andare in modalità riposo, utile per una coda notturna. Solo se almeno un caricamento è riuscito (non dopo uno Stop o se sono falliti tutti). Disattivato per impostazione predefinita. Alcuni firmware rifiutano la modalità riposo; riceverai un avviso se questa PS5 lo fa.",
"upload_wake_for_uploads_hint_ps5": "Quando un caricamento attende questa PS5 in modalità riposo, inviale un segnale di riattivazione e continua appena il suo helper è tornato. Serve la riattivazione configurata per questa PS5 nella schermata Connessione. Attivato per impostazione predefinita.",
"install_path_fallback_hint_ps5": "Un'ultima risorsa per un pacchetto già su questa PS5, quando lo rifiuta dalla sua memoria e non riesce nemmeno a prenderlo da questo computer. Usato solo per un gioco base non installato, quindi non può rimuovere nulla. Non collaudato: ha funzionato sul firmware 11.20 ed è rifiutato su 13.60, per questo si imposta per ogni PS5. Se lo provi, segnala se ha funzionato.",
"settings_group_ps5_elsewhere": "Altro per questa PS5",
"settings_card_ps5_elsewhere": "In altre schermate",
